#define MAX_DISTANCE 200.0
#define SURFACE_DISTANCE 0.01
#define MAX_ITERATION 100
#define PI 3.141516
float ti=0.0;

vec3 palette(float t){
    vec3 a = vec3(-2.332, -0.502, 1.388);
    vec3 b = vec3(0.808, -0.972, -2.422);
    vec3 c = vec3(0.668, -0.172, -0.832);
    vec3 d = vec3(-0.362, 0.638, -0.472);
    return a + b*cos(2.0*PI*(c*t+d));
}


mat2 rot(float a){
    return mat2(cos(a),-sin(a),sin(a), cos(a));
}

float sdRoundedCylinder( vec3 p, float ra, float rb, float h ){
  vec2 d = vec2( length(p.xz)-2.0*ra+rb, abs(p.y) - h );
  return min(max(d.x,d.y),0.0) + length(max(d,0.0)) - rb;
}

float sdSphere(vec3 p, float r){
    return length(p)-r;
}

float repCylinder(vec3 p, vec3 s, float ra, float rb, float h){
    vec3 q = mod(p, s) - 0.5 * s;
    return sdRoundedCylinder(q, ra, rb, h);
}

float repSphere(vec3 p, vec3 s, float r){
    vec3 q = mod(p, s) - 0.5 * s;
    return sdSphere(q, r);
}


float smin( float a, float b, float k ) {
    float h = clamp( 0.5+0.5*(b-a)/k, 0., 1. );
    return mix( b, a, h ) - k*h*(1.0-h);
}

float getDistance(vec3 p){
    vec3 rep_vec = vec3(5.0, 2.0, 8.0);
    vec3 sphere = p;
    sphere.y += sin(iTime);
    sphere.y -= iTime;


    vec3 s_aux = vec3(0.0, 0.0, 0.0);
    float sd = 100.0;
    for(float i=0.0; i<5.3; i+=PI/3.0){
        s_aux = vec3(sphere.x+cos(iTime+i), sphere.y, sphere.z+sin(iTime+i));
        float d_aux = repSphere(s_aux, rep_vec, 0.4);
        sd = smin(sd, d_aux, 0.4);
    }

    vec3 cylinder = p; 
    cylinder.y -= iTime;
    rep_vec.y = 3.0;
    float cd = repCylinder(cylinder, rep_vec,0.3, 0.3, 0.8);
    float t = smin(cd, sd, 0.6);
    return t;
}

float rayMarch(vec3 ro, vec3 rd){
    float t = 0.0;
    int i=0;
    for(int i = 0; i<MAX_ITERATION; i++){
        vec3 p = ro+rd*t;

        p.xy += vec2(sin(t)*0.6, cos(t)*0.6);
        float d = getDistance(p);
        t += d;
        if(t>MAX_DISTANCE || d<SURFACE_DISTANCE){ti = float(i);break;}
    }
    return t;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-0.5*iResolution.xy)/iResolution.y;
    vec3 col = vec3(1.0);
    vec3 ro = vec3(0.0, 0.0, -2.0);
    vec3 rd = normalize(vec3(uv.x,(uv.y), 1.0));
    float t = rayMarch(ro, rd);
    col = vec3(palette(t*.001) + float(ti)*.005);
    col = pow(col, vec3(0.4545));
    fragColor = vec4(col, 1.0);
}
